/* prog51_union_find.c
 *
 * Re‑implementation of the original binary (prog51_union_find).
 * The program works on a fixed universe of 10 elements (0‑9) and supports
 * the commands described below.  It reproduces exactly the output that the
 * original obfuscated binary produced for any given command‑line arguments.
 *
 * Commands (taken from argv, after the program name):
 *
 *   U a b   – union the sets containing a and b, prints   "UNION a b"
 *   F a b   – find the root of a, prints   "FIND a=root"
 *             then prints "YES" if a and b are in the same set,
 *             otherwise prints "NO".
 *   C a b   – dummy command, always prints "INVALID".
 *   any other token – prints "INVALID".
 *
 * All integer arguments must be decimal numbers in the range 0‑9.
 * If a command does not have enough following arguments, the program prints
 * "INVALID" and skips only the command token.
 * If the integer arguments are present but out of range, the program prints
 * "INVALID" and skips the command together with its two arguments.
 *
 * If the program is started without any command line arguments
 * (argc < 2) it prints "NOOP" and terminates.
 *
 * The implementation uses union‑by‑rank with path compression, exactly as
 * the original binary does.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_ELEM 10          /* elements are 0 … 9 */

static int parent[MAX_ELEM];
static int rankv[MAX_ELEM];

/* initialise the disjoint‑set structure */
static void dsu_init(void) {
    for (int i = 0; i < MAX_ELEM; ++i) {
        parent[i] = i;
        rankv[i] = 0;
    }
}

/* find with path compression */
static int dsu_find(int x) {
    if (parent[x] != x)
        parent[x] = dsu_find(parent[x]);
    return parent[x];
}

/* union by rank */
static void dsu_union(int x, int y) {
    int rx = dsu_find(x);
    int ry = dsu_find(y);
    if (rx == ry) return;               /* already together */

    if (rankv[rx] < rankv[ry]) {
        parent[rx] = ry;
    } else if (rankv[rx] > rankv[ry]) {
        parent[ry] = rx;
    } else {
        parent[ry] = rx;
        rankv[rx]++;                    /* increase rank of new root */
    }
}

/* check whether a string is a decimal integer in [0,9] */
static bool parse_arg(const char *s, int *out) {
    char *endptr;
    long v = strtol(s, &endptr, 10);
    if (*endptr != '\0') return false;   /* not a pure number */
    if (v < 0 || v >= MAX_ELEM) return false;
    *out = (int)v;
    return true;
}

int main(int argc, char *argv[])
{
    dsu_init();

    if (argc < 2) {               /* no commands at all */
        puts("NOOP");
        return 0;
    }

    int i = 1;                     /* start after program name */
    while (i < argc) {
        const char *cmd = argv[i];

        /* ------------------- UNION ------------------- */
        if (strcmp(cmd, "U") == 0) {
            if (i + 2 >= argc) {                 /* not enough arguments */
                puts("INVALID");
                ++i;                             /* skip only the command */
                continue;
            }
            int a, b;
            if (!parse_arg(argv[i + 1], &a) ||
                !parse_arg(argv[i + 2], &b)) {
                puts("INVALID");
                i += 3;                         /* skip command + args */
                continue;
            }
            dsu_union(a, b);
            printf("UNION %d %d\n", a, b);
            i += 3;
        }
        /* ------------------- FIND ------------------- */
        else if (strcmp(cmd, "F") == 0) {
            if (i + 2 >= argc) {
                puts("INVALID");
                ++i;
                continue;
            }
            int a, b;
            if (!parse_arg(argv[i + 1], &a) ||
                !parse_arg(argv[i + 2], &b)) {
                puts("INVALID");
                i += 3;
                continue;
            }
            int root_a = dsu_find(a);
            printf("FIND %d=%d\n", a, root_a);
            int root_b = dsu_find(b);
            puts(root_a == root_b ? "YES" : "NO");
            i += 3;
        }
        /* ------------------- C (dummy) ------------------- */
        else if (strcmp(cmd, "C") == 0) {
            if (i + 2 >= argc) {
                puts("INVALID");
                ++i;
                continue;
            }
            int a, b;
            if (!parse_arg(argv[i + 1], &a) ||
                !parse_arg(argv[i + 2], &b)) {
                puts("INVALID");
                i += 3;
                continue;
            }
            /* The original binary printed INVALID for a valid C command */
            puts("INVALID");
            i += 3;
        }
        /* ------------------- unknown token ------------------- */
        else {
            puts("INVALID");
            ++i;
        }
    }
    return 0;
}
